    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are too small to fit common items
    // but large enough to waste space. We favor residuals that are either 0 or large.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 - (post_residual as f64 * 2.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Further reward perfect fits for the next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 3. Fragmentation Control: If this is the only bin that fits the item, 
    // prioritize using it unless the residual is disastrously small.
    if fitting_bins_count == 1 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Harmonic Scaling: Penalize opening new bins unless the current open bins are very full.
    // If bin_residual == bin_capacity, we are evaluating a NEW bin.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / bin_capacity as f64);
        // Only open a new bin if existing bins are already quite full (e.g., > 75%)
        if avg_fill < 0.75 {
            score += 60.0;
        } else {
            score -= 10.0; // Allow new bin if existing ones are saturated
        }
    }

    // 5. Progression Weighting: As we approach the end of the stream, 
    // become more aggressive about packing tightly (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

