pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) logic: prioritize smaller post_residual
    // 2. Harmonic penalty: penalize small remainders that cannot fit likely future items
    // If post_residual is small but not zero, it's often wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead integration: prioritize bins that leave space for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent fit: leaves room for the next item
            score -= 40.0;
        } else {
            // Poor fit: next item will force a new bin
            score += 15.0;
        }
    }

    // 4. Threshold logic: if this is the only fitting bin, don't open a new one unless it's a perfect fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin logic: Only open a new bin if the existing options leave very little room
    // or if the current bin is significantly worse than the average
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && post_residual > (mean_residual as u32 + 20) {
            score -= 10.0;
        } else {
            score += 45.0; // Heavy penalty for opening new bins unnecessarily
        }
    }

    // 6. Harmonic Class Bias: prioritize bins that result in multiples of 20 (common item sizes)
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Best-Fit (minimize post_residual)
    let mut score = post_res;

    // Penalty for creating "sliver" space: post_residual < 10 is often unusable.
    // We penalize these gaps exponentially, but taper the penalty as we approach the end of the stream.
    if post_residual < 10 && post_residual > 0 {
        score += (10.0 - post_res).powi(2) * (1.0 - progress);
    }

    // Lookahead coupling: If a bin can fit the next item, reward lower post_residuals
    // that leave enough room for the next item, or penalize if we block future fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else {
            score += (next_item_size as f64 - post_res) * 2.0;
        }
    }

    // Global state awareness: If fitting_bins_count is low, we are running out of options.
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other fit exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one is available.
            score += 40.0 * (1.0 - progress);
        }
    } else {
        // Encourage balanced filling of open bins by comparing to the mean.
        // If this bin is significantly emptier than the mean, prioritize it.
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin:
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    // We penalize it based on how many bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 2. Lookahead matching:
    // If the post_residual is close to the next_item_size, we reward this placement.
    // We prioritize bins that create a "perfect fit" for the upcoming item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;

        // Bonus for creating a bin that can definitely fit the next item:
        if post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // 3. Mean residual balancing:
    // Avoid creating bins that are significantly more empty than the current average,
    // which helps keep bin filling levels consistent.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 4. Scarcity heuristic:
    // If this is the only bin that can fit the current item, prioritize it heavily
    // to avoid the cost of opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Progression damping:
    // As we near the end of the stream, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base score is the post-placement residual (Best Fit principle)
    let mut score = post;

    // Penalty for creating a "sliver" (fragmentation)
    // Small residuals (1-9) are highly undesirable as they rarely fit future items
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead interaction: 
    // If we have a next item, prefer bins that can accommodate it.
    // If current bin can't fit next_item_size, penalize based on progress.
    if next_item_size > 0 {
        let fits_next = if post >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= fits_next * 25.0 * (1.0 - progress);
    }

    // Dynamic pressure: 
    // As the stream progresses, prioritize closing bins (lower residual) 
    // to avoid leaving many half-empty bins at the end.
    score += (open_bins_count as f64) * progress * 5.0;

    // Favor bins that are already "tight" relative to the mean residual,
    // but only if we have multiple options (fitting_bins_count > 1).
    if fitting_bins_count > 1 {
        let deviation = (residual - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Threshold logic for opening a new bin:
    // If the bin is brand new (residual == capacity), we only choose it
    // if the average post_residual of filling existing bins would be very poor.
    if bin_residual == bin_capacity {
        score = 45.0 + (mean_residual * 0.2);
    }

    score
}
